VALUES('tnv-lau-dai-ha-noi','🌱 XANH SKY FIRST TUYỂN TÌNH NGUYỆN VIÊN LÂU DÀI TẠI HÀ NỘI','Đăng ký đồng hành lâu dài cùng Xanh Sky First tại Hà Nội. Hồ sơ được tiếp nhận trực tiếp trên hệ thống và có mã riêng để tra cứu trạng thái.','volunteer','open','[{"id":"dob","type":"date","label":"Ngày sinh","required":true},{"id":"facebook","type":"url","label":"Facebook cá nhân","required":true,"placeholder":"https://facebook.com/..."},{"id":"school","type":"text","label":"Trường / Đơn vị đang học tập, làm việc","required":true},{"id":"location","type":"text","label":"Khu vực đang sinh sống","required":true,"placeholder":"Quận/Huyện, Tỉnh/Thành phố"},{"id":"hanoi_offline","type":"radio","label":"Bạn có thể tham gia hoạt động trực tiếp tại Hà Nội?","required":true,"options":["Có","Có, nhưng cần sắp xếp trước","Hiện chỉ có thể tham gia online"]},{"id":"availability","type":"textarea","label":"Thời gian bạn có thể tham gia","required":true,"placeholder":"Ví dụ: tối Thứ 3, Thứ 5; cuối tuần..."},{"id":"area","type":"checkbox","label":"Mảng bạn muốn tham gia","required":true,"options":["Môi trường & sống xanh","Hoạt động cộng đồng","Truyền thông","Nội dung","Thiết kế","Sự kiện","Dự án & sáng kiến","Hậu cần","Khác"]},{"id":"skills","type":"textarea","label":"Kỹ năng / thế mạnh của bạn","required":true},{"id":"experience","type":"textarea","label":"Kinh nghiệm hoặc hoạt động bạn từng tham gia","required":false},{"id":"reason","type":"textarea","label":"Vì sao bạn muốn đồng hành cùng Xanh Sky First?","required":true},{"id":"contribution","type":"textarea","label":"Bạn mong muốn đóng góp điều gì cho Xanh Sky First?","required":true},{"id":"cv","type":"file","label":"CV / Portfolio / tài liệu giới thiệu","required":false},{"id":"photo","type":"file","label":"Ảnh cá nhân","required":false,"accept":"image/*"},{"id":"signature","type":"signature","label":"Chữ ký xác nhận của người đăng ký","required":true,"description":"Ký trực tiếp để xác nhận thông tin đã cung cấp là chính xác."},{"id":"truth","type":"consent","label":"Tôi xác nhận các thông tin trong hồ sơ là đúng và đồng ý để Xanh Sky First liên hệ phục vụ quá trình tiếp nhận tình nguyện viên.","required":true}]','{"confirmation_title":"Đã nhận hồ sơ tình nguyện viên","confirmation_message":"Xanh Sky First đã ghi nhận hồ sơ của bạn. Vui lòng lưu mã hồ sơ để tra cứu trạng thái xử lý.","confirmation_email":true,"closed_message":"Đợt tiếp nhận tình nguyện viên này hiện đã đóng.","require_guardian_consent":false,"guardian_note":""}',NULL,NULL,NULL,NULL,NULL,NULL,datetime('now'),datetime('now'));
